import{_ as s,o as i,c as a,a2 as t}from"./chunks/framework.B3-dzFNu.js";const u=JSON.parse('{"title":"Install or run from source","description":"","frontmatter":{},"headers":[],"relativePath":"get-started/index.md","filePath":"get-started/index.md","lastUpdated":1793496711000}'),n={name:"get-started/index.md"};function r(o,e,l,h,p,d){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="install-or-run-from-source" tabindex="-1">Install or run from source <a class="header-anchor" href="#install-or-run-from-source" aria-label="Permalink to &quot;Install or run from source&quot;">​</a></h1><p>Start with a review that needs no API key. Connect a model after that works.</p><p>For pull-request reviews instead, use <a href="/projects/redline/get-started/github-actions">GitHub Actions setup</a>. You do not need the local CLI for that path.</p><h2 id="_1-check-the-prerequisites" tabindex="-1">1. Check the prerequisites <a class="header-anchor" href="#_1-check-the-prerequisites" aria-label="Permalink to &quot;1. Check the prerequisites&quot;">​</a></h2><p>For the first review, you need:</p><ul><li>Node.js 24;</li><li>Git on your trusted PATH;</li><li>a Git repository with at least one commit.</li></ul><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>Linux, macOS, and Windows each have native x64 and ARM64 CLI tests. Pi and OpenCode are installed separately when you <a href="/projects/redline/get-started/configuration">connect a model</a>. The safe trial uses neither. It also disables indexing, so it does not need Python or an external indexer.</p><h2 id="_2-choose-how-to-run-redline" tabindex="-1">2. Choose how to run Redline <a class="header-anchor" href="#_2-choose-how-to-run-redline" aria-label="Permalink to &quot;2. Choose how to run Redline&quot;">​</a></h2><h3 id="install-a-published-npm-version" tabindex="-1">Install a published npm version <a class="header-anchor" href="#install-a-published-npm-version" aria-label="Permalink to &quot;Install a published npm version&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ignore-scripts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @dragoscirjan/redline</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>This requires a published package. If npm reports <code>E404</code>, publication may not be available yet; use the source checkout below. Do not install the unscoped <code>redline</code> package as a substitute.</p><p>To select a specific published version, use <code>@dragoscirjan/redline@VERSION</code> and replace <code>VERSION</code> with its exact version number.</p><h3 id="use-a-source-checkout" tabindex="-1">Use a source checkout <a class="header-anchor" href="#use-a-source-checkout" aria-label="Permalink to &quot;Use a source checkout&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/dragoscirjan/redline.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redline</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/redline.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>The CLI runs directly on Node.js 24. You do not need to install development dependencies to run the CLI. Dependency installation is for building the documentation and running development tests.</p><p>When reviewing another repository, stay in the Redline checkout and select the target explicitly:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/redline.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> review</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repository</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/your/repository</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --indexing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disabled</span></span></code></pre></div><p>Replace <code>/path/to/your/repository</code> with an existing Git repository. Paths with spaces need quotes.</p><h2 id="_3-run-your-first-review" tabindex="-1">3. Run your first review <a class="header-anchor" href="#_3-run-your-first-review" aria-label="Permalink to &quot;3. Run your first review&quot;">​</a></h2><p>Follow <a href="/projects/redline/get-started/first-review">Run your first review</a> for a disposable example with an expected result. It makes no model request and does not change the reviewed files.</p><p>After that, <a href="/projects/redline/get-started/configuration">connect Pi or OpenCode to a model</a>, then use the <a href="/projects/redline/commands">command recipes</a> in your own repository.</p>`,22)])])}const k=s(n,[["render",r]]);export{u as __pageData,k as default};
